package agent

import("bytes";"context";"encoding/json";"errors";"fmt";"io";"math/rand";"net";"net/http";"net/url";"strings";"time";"github.com/example-user/runnerhub/internal/provider")
type ClientConfig struct{ControlPlaneURL string;EnrollmentToken string;Name string;Provider string;AgentVersion string;HTTPClient *http.Client;AllowInsecureHTTP bool}
type Client struct{cfg ClientConfig;http *http.Client;providers map[string]provider.Provider;hostID string;token string;poll time.Duration}
func NewClient(cfg ClientConfig,providers map[string]provider.Provider)(*Client,error){if cfg.ControlPlaneURL==""||cfg.EnrollmentToken==""||cfg.Name==""{return nil,errors.New("control plane url, enrollment token and name required")};u,err:=url.Parse(cfg.ControlPlaneURL);if err!=nil||u.Host==""||u.User!=nil||u.RawQuery!=""||u.Fragment!=""{return nil,errors.New("control plane url must contain scheme, host, and optional path")};if u.Scheme!="https"&&!(u.Scheme=="http"&&(cfg.AllowInsecureHTTP||loopbackHost(u.Hostname()))){return nil,errors.New("control plane url must use https; set AllowInsecureHTTP only on a separately protected network")};cfg.ControlPlaneURL=strings.TrimRight(cfg.ControlPlaneURL,"/");h:=cfg.HTTPClient;if h==nil{h=&http.Client{Timeout:30*time.Second}};return &Client{cfg:cfg,http:h,providers:providers,poll:2*time.Second},nil}
func(c *Client)Run(ctx context.Context)error{p:=c.providers[c.cfg.Provider];if p==nil{return fmt.Errorf("provider %q not configured",c.cfg.Provider)};backoff:=time.Second;for{if c.hostID==""||c.token==""{if err:=c.enroll(ctx,p);err!=nil{if err:=waitBackoff(ctx,backoff);err!=nil{return err};backoff=minDuration(backoff*2,30*time.Second);continue};backoff=time.Second};if err:=c.cycle(ctx,p);err!=nil&&!errors.Is(err,context.Canceled){if strings.Contains(err.Error(),"returned 401"){c.hostID,c.token="",""};if err:=waitBackoff(ctx,backoff);err!=nil{return err};backoff=minDuration(backoff*2,30*time.Second);continue};backoff=time.Second;select{case<-ctx.Done():return ctx.Err();case<-time.After(c.poll):}}}
func(c *Client)enroll(ctx context.Context,p provider.Provider)error{cap,err:=p.Capabilities(ctx);if err!=nil{return err};var enrolled EnrollResponse;if err:=c.do(ctx,http.MethodPost,"/api/v1/agent/enroll",EnrollRequest{Name:c.cfg.Name,Provider:c.cfg.Provider,Capabilities:cap,AgentVersion:c.cfg.AgentVersion},&enrolled,c.cfg.EnrollmentToken);err!=nil{return err};c.hostID,c.token=enrolled.HostID,enrolled.AgentToken;if enrolled.PollIntervalSeconds>0{c.poll=time.Duration(enrolled.PollIntervalSeconds)*time.Second};return nil}
func(c *Client)cycle(ctx context.Context,p provider.Provider)error{cap,err:=p.Capabilities(ctx);if err!=nil{return err};if err:=c.do(ctx,http.MethodPost,"/api/v1/agent/heartbeat",Heartbeat{HostID:c.hostID,At:time.Now().UTC(),Capabilities:cap},nil,c.token);err!=nil{return err};var cmds []Command;if err:=c.do(ctx,http.MethodGet,"/api/v1/agent/commands?host_id="+url.QueryEscape(c.hostID),nil,&cmds,c.token);err!=nil{return err};for _,cmd:=range cmds{res:=c.execute(ctx,p,cmd);if err:=c.postResult(ctx,res);err!=nil{return err}};return nil}
func(c *Client)postResult(ctx context.Context,res CommandResult)error{delay:=250*time.Millisecond;var last error;for attempt:=0;attempt<5;attempt++{if err:=c.do(ctx,http.MethodPost,"/api/v1/agent/results",res,nil,c.token);err==nil{return nil}else{last=err};if err:=waitBackoff(ctx,delay);err!=nil{return err};delay=minDuration(delay*2,4*time.Second)};return last}
func(c *Client)execute(ctx context.Context,p provider.Provider,cmd Command)CommandResult{r:=CommandResult{CommandID:cmd.ID,WorkerID:cmd.WorkerID,At:time.Now().UTC()};switch cmd.Type{case CommandCreate:if cmd.Spec==nil{r.SafeError="missing worker spec";return r};h,err:=p.Create(ctx,*cmd.Spec);if err!=nil{r.SafeError=safe(err);return r};r.OK=true;r.Handle=&h;case CommandInspect:if cmd.Handle==nil{r.SafeError="missing worker handle";return r};s,err:=p.Inspect(ctx,*cmd.Handle);if err!=nil{r.SafeError=safe(err);return r};r.OK=true;r.State=&s;case CommandStop:if cmd.Handle==nil{r.SafeError="missing worker handle";return r};if err:=p.Stop(ctx,*cmd.Handle);err!=nil{r.SafeError=safe(err);return r};r.OK=true;case CommandDelete:if cmd.Handle==nil{r.SafeError="missing worker handle";return r};if err:=p.Delete(ctx,*cmd.Handle);err!=nil{r.SafeError=safe(err);return r};r.OK=true;default:r.SafeError="unsupported command type"};return r}
func(c *Client)do(ctx context.Context,method,path string,body any,out any,bearer string)error{var rd io.Reader;if body!=nil{b,err:=json.Marshal(body);if err!=nil{return err};rd=bytes.NewReader(b)};req,err:=http.NewRequestWithContext(ctx,method,c.cfg.ControlPlaneURL+path,rd);if err!=nil{return err};if bearer!=""{req.Header.Set("Authorization","Bearer "+bearer)};if body!=nil{req.Header.Set("Content-Type","application/json")};resp,err:=c.http.Do(req);if err!=nil{return err};defer resp.Body.Close();if refreshed:=resp.Header.Get("X-RunnerHub-Agent-Token");refreshed!=""{c.token=refreshed};if resp.StatusCode<200||resp.StatusCode>=300{b,_:=io.ReadAll(io.LimitReader(resp.Body,1024));return fmt.Errorf("control plane returned %d: %s",resp.StatusCode,strings.TrimSpace(string(b)))};if out!=nil{return json.NewDecoder(resp.Body).Decode(out)};return nil}
func safe(err error)string{s:=err.Error();if len(s)>512{s=s[:512]};return s}
func waitBackoff(ctx context.Context,d time.Duration)error{jitter:=time.Duration(rand.Int63n(int64(maxDuration(d/4,time.Millisecond))));t:=time.NewTimer(d+jitter);defer t.Stop();select{case<-ctx.Done():return ctx.Err();case<-t.C:return nil}}
func minDuration(a,b time.Duration)time.Duration{if a<b{return a};return b};func maxDuration(a,b time.Duration)time.Duration{if a>b{return a};return b}
func loopbackHost(host string)bool{if strings.EqualFold(host,"localhost"){return true};ip:=net.ParseIP(host);return ip!=nil&&ip.IsLoopback()}
